static std::string readFile(const char* path) {
  FILE* f = std::fopen(path, "rb");
  if (!f) return std::string();
  std::fseek(f, 0, SEEK_END);
  long n = std::ftell(f);
  std::fseek(f, 0, SEEK_SET);
  if (n < 0) {
    std::fclose(f);
    return std::string();
  }
  std::string s;
  s.resize((size_t)n);
  size_t got = std::fread(&s[0], 1, (size_t)n, f);
  std::fclose(f);
  if (got != (size_t)n) s.resize(got);
  return s;
}

static bool loadFloatArray(cJSON* obj, const char* key, std::vector<float>& out,
                           size_t expected) {
  cJSON* arr = cJSON_GetObjectItemCaseSensitive(obj, key);
  if (!arr || !cJSON_IsArray(arr)) return false;
  int n = cJSON_GetArraySize(arr);
  if (expected && (size_t)n != expected) return false;
  out.resize(n);
  for (int i = 0; i < n; ++i) {
    cJSON* item = cJSON_GetArrayItem(arr, i);
    if (!item || !cJSON_IsNumber(item)) return false;
    out[(size_t)i] = (float)item->valuedouble;
  }
  return true;
}

static int loadInt(cJSON* obj, const char* key, int fallback) {
  cJSON* item = cJSON_GetObjectItemCaseSensitive(obj, key);
  if (!item || !cJSON_IsNumber(item)) return fallback;
  return item->valueint;
}

// Bilinear resize of single-channel 8-bit image.
static std::vector<unsigned char> resizeGrey(const std::vector<unsigned char>& src,
                                             unsigned sw, unsigned sh,
                                             unsigned dw, unsigned dh) {
  std::vector<unsigned char> dst(dw * dh);
  if (sw == dw && sh == dh) {
    dst = src;
    return dst;
  }
  for (unsigned y = 0; y < dh; ++y) {
    float sy = (dh == 1) ? 0 : (float)y * (float)(sh - 1) / (float)(dh - 1);
    unsigned y0 = (unsigned)std::floor(sy);
    unsigned y1 = y0 + 1 < sh ? y0 + 1 : y0;
    float fy = sy - (float)y0;
    for (unsigned x = 0; x < dw; ++x) {
      float sx = (dw == 1) ? 0 : (float)x * (float)(sw - 1) / (float)(dw - 1);
      unsigned x0 = (unsigned)std::floor(sx);
      unsigned x1 = x0 + 1 < sw ? x0 + 1 : x0;
      float fx = sx - (float)x0;
      float v00 = src[y0 * sw + x0];
      float v10 = src[y0 * sw + x1];
      float v01 = src[y1 * sw + x0];
      float v11 = src[y1 * sw + x1];
      float v = (1 - fy) * ((1 - fx) * v00 + fx * v10) +
                fy * ((1 - fx) * v01 + fx * v11);
      int iv = (int)std::lround(v);
      if (iv < 0) iv = 0;
      if (iv > 255) iv = 255;
      dst[y * dw + x] = (unsigned char)iv;
    }
  }
  return dst;
}

