            loadFloatArray(root, "input_layer_bias", b1, (size_t)hiddenDim) &&
            loadFloatArray(root, "hidden_layer_weight", w2,
                           (size_t)hiddenDim * (size_t)hiddenDim) &&
            loadFloatArray(root, "hidden_layer_bias", b2, (size_t)hiddenDim) &&
            loadFloatArray(root, "output_layer_weight", w3,
                           (size_t)numClasses * (size_t)hiddenDim) &&
            loadFloatArray(root, "output_layer_bias", b3, (size_t)numClasses);
  cJSON_Delete(root);
  if (!ok) {
    std::fprintf(stderr, "Error: missing/invalid weight arrays in '%s'\n",
                 weightsPath);
    return 1;
  }

  // Decode PNG to 8-bit grayscale (lodepng converts from any PNG color type).
  std::vector<unsigned char> grey;
  unsigned pw = 0, ph = 0;
  unsigned err = lodepng::decode(grey, pw, ph, std::string(imagePath),
                                 LCT_GREY, 8);
  if (err) {
    std::fprintf(stderr, "Error: cannot decode PNG '%s': %s\n", imagePath,
                 lodepng_error_text(err));
    return 1;
  }
  if (pw == 0 || ph == 0 || grey.size() != (size_t)pw * ph) {
    std::fprintf(stderr, "Error: bad decoded image size\n");
    return 1;
  }

  // Target side length: sqrt(inputDim), must be square (28 for MNIST).
  unsigned side = (unsigned)std::lround(std::sqrt((double)inputDim));
  if ((int)(side * side) != inputDim) {
    // Fall back to 28x28 handling: require exact pixel count.
    if ((int)(pw * ph) != inputDim) {
      std::fprintf(stderr, "Error: image is %ux%u but model expects %d inputs\n",
                   pw, ph, inputDim);
      return 1;
    }
    side = pw;  // keep row-major as-is
  }
  std::vector<unsigned char> px;
  if (pw == side && ph == side) {
    px = grey;
  } else {
    px = resizeGrey(grey, pw, ph, side, side);
  }

  // Normalize to [0,1] like standard MNIST float input.
  std::vector<float> x((size_t)inputDim);
  for (int i = 0; i < inputDim; ++i) x[(size_t)i] = px[(size_t)i] / 255.0f;

  // Forward: Linear -> ReLU -> Linear -> ReLU -> Linear (see model.py).
  std::vector<float> h1((size_t)hiddenDim), h2((size_t)hiddenDim),
      out((size_t)numClasses);
  for (int o = 0; o < hiddenDim; ++o) {
    float s = b1[(size_t)o];
    const float* w = &w1[(size_t)o * (size_t)inputDim];
    for (int i = 0; i < inputDim; ++i) s += w[i] * x[(size_t)i];
    h1[(size_t)o] = s > 0 ? s : 0;
  }
  for (int o = 0; o < hiddenDim; ++o) {
    float s = b2[(size_t)o];
    const float* w = &w2[(size_t)o * (size_t)hiddenDim];
    for (int i = 0; i < hiddenDim; ++i) s += w[i] * h1[(size_t)i];
    h2[(size_t)o] = s > 0 ? s : 0;
  }
  for (int o = 0; o < numClasses; ++o) {
    float s = b3[(size_t)o];
    const float* w = &w3[(size_t)o * (size_t)hiddenDim];
    for (int i = 0; i < hiddenDim; ++i) s += w[i] * h2[(size_t)i];
    out[(size_t)o] = s;
  }
  int pred = 0;
  for (int i = 1; i < numClasses; ++i)
    if (out[(size_t)i] > out[(size_t)pred]) pred = i;

  std::printf("%d\n", pred);
  return 0;
}
